/**
 * What the runtime knows about this project's entities.
 */
final readonly class Catalogue implements EntityCatalogue
{
    public function __construct(
        private ContainerInterface $container,
    ) {

    }

    /**
     * @return list<string>
     */
    public function entities(): array {
        return ['Comment', 'Post'];
    }

    /**
     * @return Hydrator<object>
     */
    public function hydrator(
        string $entity,
    ): Hydrator {
        $service = match ($entity) {
            'Comment' => $this->container->get(CommentHydrator::class),
            'Post' => $this->container->get(PostHydrator::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof Hydrator);

        return $service;
    }

    public function verifiers(
        string $entity,
    ): EntityVerifiers {
        $service = match ($entity) {
            'Comment' => $this->container->get(CommentVerifiers::class),
            'Post' => $this->container->get(PostVerifiers::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntityVerifiers);

        return $service;
    }

    public function sideEffects(
        string $entity,
    ): EntitySideEffects {
        $service = match ($entity) {
            'Comment' => $this->container->get(CommentSideEffects::class),
            'Post' => $this->container->get(PostSideEffects::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntitySideEffects);

        return $service;
    }

    public function readPolicies(
        string $entity,
    ): EntityReadPolicies {
        return match ($entity) {
            'Comment' => new NoPolicies(),
            'Post' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    public function writePolicies(
        string $entity,
    ): EntityWritePolicies {
        return match ($entity) {
            'Comment' => new NoPolicies(),
            'Post' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return array<string, string> "Entity.edge" => target entity
     */
    public function edgeTargets(): array {
        return [];
    }

    /**
     * @return array<string, string> "Entity.field" => declared type
     */
    public function fieldTypes(): array {
        return [];
    }

    /**
     * @return list<string>
     */
    public function fieldNames(
        string $entity,
    ): array {
        return match ($entity) {
            'Comment' => ['createdAt', 'updatedAt', 'body'],
            'Post' => ['createdAt', 'updatedAt', 'note', 'title'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredFields(
        string $entity,
    ): array {
        return match ($entity) {
            'Comment' => [],
            'Post' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function nonNullableFields(
        string $entity,
    ): array {
        return match ($entity) {
            'Comment' => ['createdAt', 'updatedAt', 'body'],
            'Post' => ['createdAt', 'updatedAt', 'title'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredEdges(
        string $entity,
    ): array {
        return match ($entity) {
            'Comment' => [],
            'Post' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function uniqueFields(
        string $entity,
    ): array {
        return match ($entity) {
            'Comment' => [],
            'Post' => [],
            default => [],
        };
    }

    /**
     * @return array<string, Managed> "Entity.field" => policy
     */
    public function managedFields(): array {
        return [
            'Comment.createdAt' => Managed::Created,
            'Comment.updatedAt' => Managed::Modified,
            'Post.createdAt' => Managed::Created,
            'Post.updatedAt' => Managed::Modified,
        ];
    }

    /**
     * @return list<DeletionRule>
     */
    public function deletionRules(
        string $entity,
    ): array {
        return match ($entity) {
            'Comment' => CommentDeleter::rules(),
            'Post' => PostDeleter::rules(),
            default => [],
        };
    }

    public function finder(
        string $entity,
    ): object {
        $finder = match ($entity) {

            default => throw new RuntimeException(sprintf('%s declares no queries.', $entity)),
        };

        assert(is_object($finder));

        return $finder;
    }

    public function mutatorFor(
        string $entity,
        MutationBuffer $buffer,
    ): object {
        return match ($entity) {
            'Comment' => new CommentMutator($buffer),
            'Post' => new PostMutator($buffer),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return list<string>
     */
    public function queryArguments(
        string $entity,
        string $query,
    ): array {
        return match ($entity . '.' . $query) {

            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function actionArguments(
        string $entity,
        string $action,
    ): array {
        return match ($entity . '.' . $action) {

            default => [],
        };
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeCommentInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(CommentInput::class);

        assert($input instanceof CommentInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodePostInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(PostInput::class);

        assert($input instanceof PostInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeActionArguments(
        string $entity,
        string $action,
        array $args,
    ): array {
        return match ($entity) {
            'Comment' => $this->decodeCommentInputActionArguments($action, $args),
            'Post' => $this->decodePostInputActionArguments($action, $args),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @param array<string, mixed> $input
     */
    public function apply(
        string $entity,
        MutationBuffer $buffer,
        array $input,
    ): void {
        $applier = match ($entity) {
            'Comment' => $this->container->get(CommentInput::class),
            'Post' => $this->container->get(PostInput::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert(is_object($applier) && method_exists($applier, 'apply'));

        $applier->apply($buffer, $input);
    }

    /**
     * Everything the application must implement before it can start.
     *
     * @return list<string>
     */
    public function contracts(): array {
        return [];
    }
}

