use InvalidArgumentException;

/**
 * Turns raw input into pending Post changes.
 */
final readonly class PostInput
{
    public function __construct(
        private ValueDecoder $decode,
    ) {

    }

    private function note(
        mixed $value,
    ): ?string {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Post.note');
    }

    private function title(
        mixed $value,
    ): ?string {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Post.title');
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(
        MutationBuffer $buffer,
        array $input,
    ): void {
        if (array_key_exists('note', $input)) {
            $buffer->set('note', $this->note($input['note']));
        }

        if (array_key_exists('title', $input)) {
            $buffer->set('title', $this->title($input['title']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(
        string $action,
        array $args,
    ): array {
        return match ($action) {

            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

